"""Рядок 4285: колір речі оцінки з рамки, що з трьох боків у речі, а четвертим тягнеться за річ до краю фото — ДО/ПІСЛЯ.
Replay записаних відповідей «речі на фото» (VIDPOVIDI гілки claude/zhyvi-19) на фото сцени 6 стенда (`ОЦІНКА_ФІГУРИ`,
JPEG 0.92), вирізаних як `пікселіРечіП` (поле 12 %, ≤128 px); вимір — `оцінка_образу._виміри` старим і новим модулем.
Друкує: річ, слово, рамка, намальований колір, hex ДО/ПІСЛЯ і найбільшу різницю каналу RGB.
Запуск: cd джерела && python3 проби/рамка_тло_за_краєм_4285.py [ДО_РЕФ:джерела/річ_з_фото.py]"""
import base64, io, os, subprocess, sys, types; from PIL import Image, ImageDraw
Д = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, Д)
import річ_з_фото as НОВ, оцінка_образу as ОО
СТ = types.ModuleType("стара"); СТ.__file__ = os.path.join(Д, "річ_з_фото.py")
exec(subprocess.check_output(["git", "show", sys.argv[1] if len(sys.argv) > 1 else "33080eacdfa243be2790eac73616e9f678f57cd3:джерела/річ_з_фото.py"]).decode(), СТ.__dict__)
Б = [(98, 170), (190, 170), (194, 336), (214, 370), (248, 393), (266, 418), (270, 446), (264, 462), (98, 462)]
П = [[(140, 462), (268, 462), (266, 470), (256, 474), (140, 474)], [(98, 462), (136, 462), (134, 480), (100, 480)], [(98, 170), (190, 170), (190, 180), (98, 180)]]
ФІГ = {"ф1": (600, 800, "#efe9e1", [("#7d7f63", [(170, 90), (430, 90), (480, 130), (480, 440), (430, 440), (430, 470), (170, 470), (170, 440), (120, 440), (120, 130)]),
                                     ("#cfd8e3", [(250, 110), (350, 110), (350, 400), (250, 400)]), ("#6b1f2a", [(200, 520), (400, 520), (430, 760), (170, 760)])]),
       "ф2": (600, 600, "#8c96a0", [(к, [(x + з, y) for x, y in т]) for к, пд, з in (("#e6dfd2", "#6b5b4c", 0), ("#1d1c1c", "#4a4646", 260)) for к, т in [(к, Б)] + [(пд, п) for п in П]])}
НАМ = {"оливковий": "#7d7f63", "хакі": "#7d7f63", "блакитний": "#cfd8e3", "бордовий": "#6b1f2a", "вершковий": "#e6dfd2", "чорний": "#1d1c1c"}
def фото(ш, в, тло, фіг):
    im = Image.new("RGB", (ш, в), тло); [ImageDraw.Draw(im).polygon(т, fill=к) for к, т in фіг]
    b = io.BytesIO(); im.save(b, "JPEG", quality=92); return Image.open(b).convert("RGB")
ФОТО = {к: фото(*v) for к, v in ФІГ.items()}
def пікс(im, р, поле=.12):                                     # = показ.html `пікселіРечіП`
    W, H = im.size; л, в, п, н = р["ліво"], р["верх"], р["право"], р["низ"]; dx, dy = (п - л) * поле, (н - в) * поле
    л2, в2, п2, н2 = max(0, л - dx), max(0, в - dy), min(1000, п + dx), min(1000, н + dy); x0, y0 = round(л2 / 1000 * W), round(в2 / 1000 * H)
    c = im.crop((x0, y0, x0 + max(1, round((п2 - л2) / 1000 * W)), y0 + max(1, round((н2 - в2) / 1000 * H))))
    к = min(1, 128 / max(c.size)); c = c.resize((max(1, round(c.width * к)), max(1, round(c.height * к))), Image.BOX)
    return {"дані": base64.urlsafe_b64encode(c.tobytes()).decode(), "ширина": c.width, "висота": c.height,
            "ядро": {"ліво": round((л - л2) / (п2 - л2) * 1000), "верх": round((в - в2) / (н2 - в2) * 1000), "право": round((п - л2) / (п2 - л2) * 1000), "низ": round((н - в2) / (н2 - в2) * 1000)}}
def розб(а, б): return max(abs(int(а[i:i + 2], 16) - int(б[i:i + 2], 16)) for i in (1, 3, 5))
for ф in ("живі_19/А/10_ж1_оціни_образ_6б/VIDPOVIDI/seed3_02", "живі_19/А/10_ж1_оціни_образ_6б/VIDPOVIDI/seed3_09",
          "живі_12/Б/08_ж1_оціни_образ_6б/VIDPOVIDI/seed3_40", "живі_12/Б/08_ж1_оціни_образ_6б/VIDPOVIDI/seed3_47", "живі_11/Н4/VIDPOVIDI/seed3_39"):
    т = subprocess.check_output(["git", "show", "origin/claude/zhyvi-19:аудит/%s_ОЦІНКА_речі_на_фото.txt" % ф]).decode()
    речі = [р for р in ОО.речі_з_відповіді(т.split("── ВІДПОВІДЬ", 1)[1].split("\n", 1)[1], [{"ід": "ф1"}, {"ід": "ф2"}])["речі"] if р.get("рамка")]
    пікселі, інші = {р["ід"]: пікс(ФОТО[р["фото"]], р["рамка"]) for р in речі}, {р["ід"]: {і: пікс(ФОТО[і], р["рамка"]) for і in ФОТО if і != р["фото"]} for р in речі}
    виміри = []
    for М in (СТ, НОВ): ОО._РФ = М; виміри.append({х.get("ід_моделі") or х["ід"]: х for х in ОО._виміри(речі, пікселі, інші, "#deb295")})
    for р in речі:
        нам, рр = НАМ.get(р["колір"]), р["рамка"]
        ряд = ["%s%s %s" % ((в[р["ід"]].get("вимір") or {}).get("hex"), "→" + в[р["ід"]]["фото"] if в[р["ід"]]["фото"] != р["фото"] else "",
                             розб(в[р["ід"]]["вимір"]["hex"], нам) if нам and (в[р["ід"]].get("вимір") or {}).get("hex") else "—") for в in виміри]
        print("%s %-5s %-10s %s·%d–%d×%d–%d нам %s | ДО %s | ПІСЛЯ %s" % (ф.split("/")[0][5:] + "/" + ф[-8:], р["ід"], р["колір"], р["фото"], рр["ліво"], рр["право"], рр["верх"], рр["низ"], нам, *ряд))
